import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

/**
 * CANONICAL CONTRACT FIXTURES — generated by the REAL route handler, never written by hand.
 *
 * Each fixture is the exact response body (`await res.text()`, byte for byte) that the exported `GET` returns for a
 * fake data source with synthetic counts, at a fixed clock. The Agentai consumer tests its parser against
 * byte-identical copies of these files.
 *
 *   Check (default, CI):  fails when a regenerated body differs from the committed file by one byte (drift).
 *   Regenerate:           UPDATE_CONTRACT_FIXTURES=1 npx vitest run lib/api/registrations-daily-contract-fixtures.test.ts
 */

let rpcResult: { data: unknown; error: unknown } = { data: null, error: null };

vi.mock("server-only", () => ({}));
vi.mock("@/lib/supabase/admin", () => ({
  createAdminClient: () => ({ rpc: async () => rpcResult }),
}));

import { GET } from "@/app/api/internal/registrations-daily/v1/route";

const FIXTURES = join(__dirname, "..", "..", "..", "..", "docs", "contracts", "fixtures");
const TOKEN = "f".repeat(40);
const GENERATED_AT = "2026-11-14T06:00:00.000Z";
const DAY = "2026-11-13";

const split = (REAL: number, TEST = 0, INTERNAL = 0) => ({ REAL, TEST, INTERNAL });

/** Synthetic aggregate: workers.new = 2 (→ suppressed), students all null (→ unmeasured), TEST/INTERNAL non-zero. */
const SYNTHETIC_AGGREGATE = {
  groups: {
    workers: { new: split(2, 3, 1), active7d: split(40, 9, 1), active30d: split(120, 10, 2) },
    employers: { new: split(0, 1, 0), active7d: split(6, 4, 0), active30d: split(15, 4, 0) },
    agencies: { new: split(0), active7d: split(0), active30d: split(3, 0, 1) },
    students: { new: null, active7d: null, active30d: null },
    education: { new: split(0), active7d: split(0, 2, 0), active30d: split(5, 2, 0) },
  },
};

async function call(authorization: string | null): Promise<Response> {
  const headers: Record<string, string> = authorization ? { authorization } : {};
  return GET(new Request(`https://labourmarket.ai/api/internal/registrations-daily/v1?day=${DAY}`, { headers }));
}

const CASES: ReadonlyArray<{ file: string; status: number; arrange: () => void; authorization: string | null }> = [
  {
    file: "lm-registrations-daily-v1.sample.json",
    status: 200,
    arrange: () => (rpcResult = { data: SYNTHETIC_AGGREGATE, error: null }),
    authorization: `Bearer ${TOKEN}`,
  },
  {
    file: "lm-registrations-daily-v1.error-503.sample.json",
    status: 503,
    arrange: () => (rpcResult = { data: null, error: { code: "PGRST202", message: "function not found" } }),
    authorization: `Bearer ${TOKEN}`,
  },
  {
    file: "lm-registrations-daily-v1.error-401.sample.json",
    status: 401,
    arrange: () => (rpcResult = { data: SYNTHETIC_AGGREGATE, error: null }),
    authorization: `Bearer ${"w".repeat(40)}`,
  },
];

beforeEach(() => {
  vi.useFakeTimers();
  vi.setSystemTime(Date.parse(GENERATED_AT));
  vi.stubEnv("SUPPLY_FEED_BEARER_TOKEN", TOKEN);
});

afterEach(() => {
  vi.useRealTimers();
  vi.unstubAllEnvs();
});

describe("contract fixtures are real route responses (byte-compared; drift fails)", () => {
  it.each(CASES)("$file", async ({ file, status, arrange, authorization }) => {
    arrange();
    const res = await call(authorization);
    expect(res.status).toBe(status);
    const bytes = await res.text();
    const path = join(FIXTURES, file);
    if (process.env.UPDATE_CONTRACT_FIXTURES === "1") writeFileSync(path, bytes, "utf8");
    expect(readFileSync(path, "utf8")).toBe(bytes);
  });

  it("the 200 sample holds all five groups, a suppressed 1–2 count, an unmeasured group, and no personal data", () => {
    const text = readFileSync(join(FIXTURES, "lm-registrations-daily-v1.sample.json"), "utf8");
    const sample = JSON.parse(text);
    expect(sample.definitionVersion).toBe("lm-registrations-daily/v1");
    expect(sample.generatedAt).toBe(GENERATED_AT);
    expect(Object.keys(sample.groups)).toEqual(["workers", "employers", "agencies", "students", "education"]);
    expect(sample.groups.workers.new).toEqual({ count: null, suppressed: true });
    for (const m of ["new", "active7d", "active30d"]) {
      expect(sample.groups.students[m]).toEqual({ count: null, suppressed: false, unmeasured: true });
    }
    expect(text).not.toContain("@");
    expect(text).not.toMatch(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i);
    // TEST / INTERNAL synthetic counts (e.g. workers.new TEST = 3) never appear as a published REAL count.
    expect(text).not.toMatch(/TEST|INTERNAL/);
  });
});
